  "banners/banner-1/styles.css": "body {\r\n  margin: 0;\r\n  color: #222222;\r\n  min-height: 100vh;\r\n  background: url(\"./bg.jpg\");\r\n  background-size: cover;\r\n  background-position: 50% -150px;\r\n  font-family: \"Euclid Circular B\", \"Poppins\";\r\n}\r\n\r\n* {\r\n  box-sizing: border-box;\r\n}\r\n\r\n.typed-message-page::before {\r\n  content: \"\";\r\n  z-index: 0;\r\n  position: absolute;\r\n  inset: 0;\r\n  background: linear-gradient(rgb(0 0 0 / 86%), rgb(0 0 0 / 0%) 120%);\r\n}\r\n\r\n.typed-message-page nav {\r\n  position: fixed;\r\n  top: 8px;\r\n  width: 100%;\r\n  z-index: 2;\r\n  display: flex;\r\n  padding: 0 40px;\r\n  align-items: center;\r\n  height: 96px;\r\n  color: #f7f7f7;\r\n}\r\n\r\n.typed-message-search {\r\n  position: relative;\r\n  flex: 1 1 auto;\r\n}\r\n\r\n.typed-message-search span {\r\n  position: absolute;\r\n  z-index: 3;\r\n  top: 50%;\r\n  left: 16px;\r\n  translate: 0 -50%;\r\n}\r\n\r\n.typed-message-search input {\r\n  border: 0;\r\n  border-radius: 40px;\r\n  height: 50px;\r\n  background: rgb(255 255 255 / 10%);\r\n  backdrop-filter: blur(10px);\r\n  width: 100%;\r\n  font-family: inherit;\r\n  font-size: 16px;\r\n  padding-left: 50px;\r\n}\r\n\r\n.typed-message-search input::placeholder {\r\n  color: rgb(255 255 255 / 60%);\r\n}\r\n\r\n.typed-message-banner {\r\n  position: relative;\r\n  height: 100vh;\r\n  border-radius: 50px;\r\n  color: #ffffff;\r\n}\r\n\r\n.typed-message-banner-content {\r\n  position: relative;\r\n  z-index: 3;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 30px;\r\n  height: 100vh;\r\n}\r\n\r\n.typed-message-wrapper {\r\n  position: absolute;\r\n  top: 50%;\r\n  left: 50%;\r\n  translate: -50% -80%;\r\n  font-size: 48px;\r\n  font-weight: 400;\r\n  width: 80%;\r\n  line-height: 1.2;\r\n}\r\n\r\n@keyframes button-appear {\r\n  0% {\r\n    opacity: 0;\r\n    visibility: hidden;\r\n  }\r\n  100% {\r\n    opacity: 1;\r\n    visibility: visible;\r\n  }\r\n}\r\n\r\n.typed-message-wrapper button {\r\n  position: absolute;\r\n  left: 50%;\r\n  top: 90%;\r\n  translate: -50% 10%;\r\n  font-family: inherit;\r\n  background: rgb(255 255 255 / 5%);\r\n  backdrop-filter: blur(12px);\r\n  color: #f9f9f9;\r\n  padding: 16px 28px 16px 32px;\r\n  border-radius: 64px;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 9px;\r\n  border: 2px solid rgb(255 255 255 / 10%);\r\n  font-size: 18px;\r\n  scale: 1.12;\r\n  transition: 0.3s;\r\n  animation: button-appear 0.275s 1.35s backwards ease-in-out;\r\n}\r\n\r\n.typed-message-wrapper button.hidden {\r\n  opacity: 0;\r\n  visibility: hidden;\r\n}\r\n\r\n.typed-message-wrapper button > span {\r\n  font-size: 18px;\r\n  translate: 0 2px;\r\n}\r\n\r\n.typed-message-banner-content > button {\r\n  color: #f7f7f7;\r\n  font-family: inherit;\r\n  padding: 0 32px;\r\n  height: 64px;\r\n  border-radius: 32px;\r\n  border: 0;\r\n  font-size: 22px;\r\n  align-self: baseline;\r\n}\r\n\r\n.typed-message-logo {\r\n  width: 140px;\r\n  padding-right: 40px;\r\n}\r\n\r\n.typed-message-links {\r\n  display: flex;\r\n  width: 140px;\r\n  justify-content: flex-end;\r\n  align-items: center;\r\n  gap: 16px;\r\n}\r\n\r\n.typed-message-links span {\r\n  font-size: 24px;\r\n}\r\n\r\n.message {\r\n  font-weight: inherit;\r\n  line-height: 1.55;\r\n  font-size: 58px;\r\n  text-align: center;\r\n  text-shadow: 0 1px 10px rgb(0 0 0 / 10%);\r\n}\r\n",
  "banners/banner-1/main.js": "const message = document.querySelector(\".message\");\r\n\r\nconst s = new SplitText(message, {\r\n  type: \"lines,words\",\r\n});\r\n\r\nconst tl = gsap.timeline({\r\n  delay: 0.5,\r\n  repeatDelay: 0.5,\r\n  repeat: 10,\r\n});\r\n\r\ntl.addLabel(\"enter\");\r\n\r\ntl.fromTo(\r\n  s.words,\r\n  { yPercent: 100 },\r\n  {\r\n    yPercent: 0,\r\n    ease: \"circ.out\",\r\n    stagger: 0.2,\r\n  },\r\n  \"enter\"\r\n);\r\n\r\ntl.fromTo(\r\n  s.words,\r\n  { opacity: 0 },\r\n  {\r\n    opacity: 1,\r\n    ease: \"power1.out\",\r\n    stagger: 0.2,\r\n  },\r\n  \"enter\"\r\n);\r\n\r\ntl.addPause();\r\n\r\ntl.to(\r\n  s.words,\r\n  {\r\n    yPercent: -200,\r\n    opacity: 0,\r\n    ease: \"circ.in\",\r\n    stagger: 0.1,\r\n    duration: 0.4,\r\n  },\r\n  \"exit\"\r\n);\r\n\r\ntl.to(\r\n  s.words,\r\n  {\r\n    opacity: 0,\r\n    ease: \"power1.in\",\r\n    stagger: 0.1,\r\n    duration: 0.4,\r\n  },\r\n  \"exit\"\r\n);\r\n\r\nconst handleClick = () => {\r\n  tl.play();\r\n  const button = document.querySelector(\".typed-message-wrapper button\");\r\n  button.classList.add(\"hidden\");\r\n};\r\n",
