  "barras-laterales/sidebar-6/index.html": "<!doctype html>\r\n<html lang=\"en\">\r\n  <head>\r\n    <meta charset=\"UTF-8\" />\r\n    <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n    <title>Sidebars</title>\r\n    <link rel=\"stylesheet\" href=\"styles.css\" />\r\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\r\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\r\n    <link\r\n      href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600&display=swap\"\r\n      rel=\"stylesheet\"\r\n    />\r\n    <link\r\n      rel=\"stylesheet\"\r\n      href=\"https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:opsz,wght,FILL,GRAD@48,700,1,0\"\r\n    />\r\n    <link\r\n      href=\"https://unpkg.com/boxicons@2.1.4/css/boxicons.min.css\"\r\n      rel=\"stylesheet\"\r\n    />\r\n    <script src=\"https://unpkg.com/akar-icons-fonts\"></script>\r\n  </head>\r\n  <body>\r\n    <input type=\"checkbox\" name=\"toggle\" id=\"toggle\" />\r\n    <aside class=\"sidebar\">\r\n      <div class=\"header\">\r\n        <img src=\"logo.svg\" class=\"logo\" />\r\n        <img src=\"logo-text.svg\" class=\"logo-text\" />\r\n      </div>\r\n      <nav>\r\n        <button class=\"active\" type=\"button\">\r\n          <i class=\"ai-home-alt1\"></i>\r\n          <p>Home</p>\r\n        </button>\r\n        <button type=\"button\">\r\n          <i class=\"ai-person\"></i>\r\n          <p>Contacts</p>\r\n        </button>\r\n        <button type=\"button\">\r\n          <i class=\"ai-shipping-box-v1\"></i>\r\n          <p>Automation</p>\r\n        </button>\r\n        <button type=\"button\">\r\n          <i class=\"ai-sparkles\"></i>\r\n          <p>Manychat AI</p>\r\n        </button>\r\n        <button type=\"button\">\r\n          <i class=\"ai-chat-dots has-badge\"></i>\r\n          <p>Inbox</p>\r\n          <span class=\"badge\">1</span>\r\n        </button>\r\n        <button type=\"button\">\r\n          <i class=\"ai-gear\"></i>\r\n          <p>Settings</p>\r\n        </button>\r\n        <label for=\"toggle\">\r\n          <span class=\"toggle-btn\"></span>\r\n        </label>\r\n      </nav>\r\n      <nav class=\"bottom\">\r\n        <button type=\"button\">\r\n          <img class=\"avatar\" src=\"avatar.png\" />\r\n          <p>Profile</p>\r\n        </button>\r\n      </nav>\r\n    </aside>\r\n  </body>\r\n</html>\r\n",
  "barras-laterales/sidebar-6/styles.css": "* {\r\n  box-sizing: border-box;\r\n}\r\n\r\nbody {\r\n  margin: 0;\r\n  background: #fbfbfb;\r\n  color: #292929;\r\n  height: 100vh;\r\n  font-family: \"Euclid Circular B\";\r\n}\r\n\r\n.sidebar {\r\n  --color-primary: #4066ff;\r\n  --color-border: #ebebeb;\r\n  position: fixed;\r\n  overflow: hidden;\r\n  top: 0;\r\n  left: 0;\r\n  bottom: 0;\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  gap: 8px;\r\n  width: 64px;\r\n  border-right: 1px solid var(--color-border);\r\n  background: #ffffff;\r\n  transition: width 0.4s;\r\n}\r\n\r\ninput:checked ~ aside {\r\n  width: 240px;\r\n}\r\n\r\nlabel {\r\n  margin-top: auto;\r\n}\r\n\r\n.toggle-btn {\r\n  display: grid;\r\n  width: 64px;\r\n  height: 40px;\r\n  background: url(\"icon-right.svg\");\r\n  background-repeat: no-repeat;\r\n  background-position: center;\r\n  background-size: 35%;\r\n  cursor: pointer;\r\n  transition: 0.1s;\r\n}\r\n\r\ninput:checked ~ aside label .toggle-btn {\r\n  background-image: url(\"icon-left.svg\");\r\n}\r\n\r\ninput {\r\n  position: fixed;\r\n  top: 20px;\r\n  right: 20px;\r\n}\r\n\r\n.header {\r\n  position: relative;\r\n  display: flex;\r\n  align-items: center;\r\n  border-bottom: 1px solid var(--color-border);\r\n  width: 100%;\r\n  height: 64px;\r\n}\r\n\r\n.logo {\r\n  position: absolute;\r\n  top: 0;\r\n  left: 0;\r\n  width: 64px;\r\n  display: grid;\r\n  min-width: 64px;\r\n  padding: 16px;\r\n}\r\n\r\n.logo-text {\r\n  position: absolute;\r\n  top: 18px;\r\n  left: 46px;\r\n  opacity: 0;\r\n  height: 32px;\r\n  transition: 0.3s;\r\n}\r\n\r\ninput:checked ~ aside .logo-text {\r\n  opacity: 1;\r\n}\r\n\r\nbutton {\r\n  cursor: pointer;\r\n}\r\n\r\n.avatar {\r\n  width: 52px;\r\n  padding: 10px;\r\n}\r\n\r\nnav {\r\n  display: flex;\r\n  flex-direction: column;\r\n  width: 100%;\r\n  flex: 1 1 auto;\r\n}\r\n\r\nnav.bottom {\r\n  flex: 0;\r\n  border-top: 1px solid var(--color-border);\r\n  padding-bottom: 16px;\r\n}\r\n\r\nnav button {\r\n  position: relative;\r\n  background: transparent;\r\n  border: 0;\r\n  font-family: inherit;\r\n  display: flex;\r\n  gap: 8px;\r\n  align-items: center;\r\n  height: 52px;\r\n  width: 52px;\r\n  padding: 0;\r\n  border-radius: 8px;\r\n  color: #707070;\r\n  margin-left: 6px;\r\n  margin-right: 6px;\r\n  transition: 0.3s;\r\n}\r\n\r\nnav button:hover {\r\n  background: #f4f4f8;\r\n}\r\n\r\ninput:checked ~ aside nav button {\r\n  width: calc(100% - 12px);\r\n}\r\n\r\nnav button.active {\r\n  background: #ededf3;\r\n}\r\n\r\nnav button p {\r\n  position: absolute;\r\n  top: 50%;\r\n  translate: 0 -50%;\r\n  left: 56px;\r\n  margin: 0;\r\n  white-space: nowrap;\r\n  font-size: 16px;\r\n  opacity: 0;\r\n  transition: 0.3s;\r\n}\r\n\r\ninput:checked ~ aside p {\r\n  opacity: 1;\r\n}\r\n\r\nnav button i {\r\n  width: 52px;\r\n  font-size: 24px;\r\n}\r\n\r\n.badge {\r\n  position: absolute;\r\n  top: 25%;\r\n  right: -2px;\r\n  translate: 0 -50%;\r\n  background: var(--color-primary);\r\n  color: #f9f9f9;\r\n  padding: 2px 6px;\r\n  border-radius: 20px;\r\n  width: 22px;\r\n  height: 22px;\r\n  display: grid;\r\n  place-items: center;\r\n  scale: 0.25;\r\n  transition: 0.3s;\r\n  font-size: 0px;\r\n}\r\n\r\ninput:checked ~ aside .badge {\r\n  opacity: 1;\r\n  scale: 1;\r\n  top: 50%;\r\n  right: 10px;\r\n  font-size: 12px;\r\n}\r\n",
