  "inicios-sesion/login-12/index.html": "<!DOCTYPE html>\r\n<html lang=\"en\">\r\n  <head>\r\n    <meta charset=\"UTF-8\" />\r\n    <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n    <title>Logins</title>\r\n    <link\r\n      rel=\"stylesheet\"\r\n      href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css\"\r\n      integrity=\"sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==\"\r\n      crossorigin=\"anonymous\"\r\n      referrerpolicy=\"no-referrer\"\r\n    />\r\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\r\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\r\n    <link\r\n      href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600&display=swap\"\r\n      rel=\"stylesheet\"\r\n    />\r\n    <link\r\n      rel=\"stylesheet\"\r\n      href=\"https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:opsz,wght,FILL,GRAD@24,400,0,0\"\r\n    />\r\n    <link rel=\"stylesheet\" href=\"styles.css\" />\r\n  </head>\r\n  <body>\r\n    <div class=\"card\">\r\n      <div class=\"hero\">\r\n        <div class=\"hero-inner\">\r\n          <h2>The easiest way to send payments securely</h2>\r\n          <h3>End to end encrypted transfers</h3>\r\n        </div>\r\n      </div>\r\n      <form>\r\n        <img src=\"logo.svg\" />\r\n        <h3>Login to your account</h3>\r\n        <div class=\"socials\">\r\n          <button class=\"social-btn\">\r\n            <img src=\"google.svg\" />\r\n            <p><span class=\"extra-text\">Login with</span> Google</p>\r\n          </button>\r\n          <button class=\"social-btn\">\r\n            <img src=\"facebook.svg\" />\r\n            <p><span class=\"extra-text\">Login with</span> Facebook</p>\r\n          </button>\r\n        </div>\r\n        <span class=\"or\"></span>\r\n        <input type=\"email\" placeholder=\"Email\" />\r\n        <input type=\"password\" placeholder=\"Password\" />\r\n        <button type=\"submit\">Login</button>\r\n      </form>\r\n    </div>\r\n  </body>\r\n</html>\r\n",
  "inicios-sesion/login-12/styles.css": "body {\r\n  height: 100vh;\r\n  margin: 0;\r\n  display: grid;\r\n  place-items: center;\r\n  background: #e8dfff;\r\n  color: #645e74;\r\n  font-family: \"Euclid Circular B\", \"Poppins\";\r\n}\r\n\r\n:root {\r\n  --color-primary: #5e3b8f;\r\n  --color-border: #d0d0d6;\r\n}\r\n\r\n* {\r\n  box-sizing: border-box;\r\n}\r\n\r\n.card {\r\n  display: flex;\r\n  flex-direction: column;\r\n  background: #ffffff;\r\n  border-radius: 22px;\r\n  padding: 20px;\r\n  width: clamp(300px, 85vw, 500px);\r\n  box-shadow: 0 50px 100px rgb(0 0 0 / 8%);\r\n}\r\n\r\n.hero,\r\nform {\r\n  flex: 1 1 50%;\r\n}\r\n\r\nh3,\r\np {\r\n  font-weight: 500;\r\n  margin: 0;\r\n}\r\n\r\n.hero {\r\n  background: url(\"hero.svg\");\r\n  background-size: cover;\r\n  background-repeat: no-repeat;\r\n  border-radius: 16px;\r\n  overflow: hidden;\r\n  font-family: \"Space Grotesk\";\r\n}\r\n\r\n.hero-inner {\r\n  display: flex;\r\n  flex-direction: column;\r\n  justify-content: center;\r\n  border-radius: inherit;\r\n  background: linear-gradient(rgb(95 69 168 / 0%), rgb(95 69 168 / 70%));\r\n  padding: 40px 66px;\r\n  height: 100%;\r\n  min-height: 170px;\r\n}\r\n\r\n.hero h2 {\r\n  font-size: 22px;\r\n  color: #ffffff;\r\n  line-height: 1.25;\r\n}\r\n\r\n.hero h3 {\r\n  margin-top: 12px;\r\n  font-size: 18px;\r\n  color: #d8d8d8;\r\n  display: none;\r\n}\r\n\r\nform {\r\n  padding: 30px 18px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 12px;\r\n}\r\n\r\nform > img {\r\n  height: 28px;\r\n  margin-top: px;\r\n  margin-bottom: 12px;\r\n}\r\n\r\nform :is(h2, h3) {\r\n  text-align: center;\r\n}\r\n\r\nform > h2 {\r\n  letter-spacing: 0.5px;\r\n  font-weight: 600;\r\n  color: var(--color-primary);\r\n}\r\n\r\nform > h3 {\r\n  font-size: 14px;\r\n  margin-bottom: 12px;\r\n}\r\n\r\nbutton,\r\ninput {\r\n  height: 44px;\r\n  border-radius: 10px;\r\n  background: transparent;\r\n  color: inherit;\r\n  font-family: inherit;\r\n  font-size: 16px;\r\n  width: 100%;\r\n  outline-color: var(--color-primary);\r\n}\r\n\r\ninput {\r\n  border: 1px solid var(--color-border);\r\n  padding: 0 2.5vw;\r\n}\r\n\r\ninput::placeholder {\r\n  color: #9c99a4;\r\n}\r\n\r\n.socials {\r\n  display: flex;\r\n  gap: 8px;\r\n}\r\n\r\n.extra-text {\r\n  display: none;\r\n}\r\n\r\n.social-btn {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  gap: 10px;\r\n  background: #f2f3f6;\r\n  border-color: transparent;\r\n  font-size: 15px;\r\n}\r\n\r\n.social-btn > img {\r\n  height: 24px;\r\n}\r\n\r\n.social-btn:first-child > img {\r\n  height: 20px;\r\n}\r\n\r\n.social-btn > p {\r\n  color: #7e7c83;\r\n}\r\n\r\nform > button[type=\"submit\"] {\r\n  color: #ffffff;\r\n  border: 0;\r\n  background: var(--color-primary);\r\n  font-size: 17px;\r\n}\r\n\r\n.or {\r\n  position: relative;\r\n  text-align: center;\r\n  height: 24px;\r\n}\r\n\r\n.or::before {\r\n  content: \"\";\r\n  position: absolute;\r\n  z-index: 0;\r\n  top: 50%;\r\n  left: 0;\r\n  width: 100%;\r\n  translate: 0 -50%;\r\n  height: 1px;\r\n  background: var(--color-border);\r\n  opacity: 0.6;\r\n}\r\n\r\n.or::after {\r\n  content: \"Or\";\r\n  position: absolute;\r\n  top: 50%;\r\n  left: 50%;\r\n  translate: -50% -50%;\r\n  z-index: 1;\r\n  background: #ffffff;\r\n  font-size: 12px;\r\n  padding: 0 12px;\r\n}\r\n\r\n@media (width >= 485px) {\r\n  .card {\r\n    width: clamp(300px, 90vw, 740px);\r\n  }\r\n\r\n  form {\r\n    padding-inline: 50px;\r\n  }\r\n\r\n  .hero-inner {\r\n    padding-right: clamp(10px, 20vw, 60px);\r\n  }\r\n\r\n  .socials {\r\n    flex-direction: column;\r\n  }\r\n\r\n  .extra-text {\r\n    display: inline;\r\n  }\r\n}\r\n\r\n@media (width >= 640px) {\r\n  .card {\r\n    flex-direction: row;\r\n    padding: 8px 0 8px 8px;\r\n  }\r\n\r\n  .hero-inner {\r\n    justify-content: center;\r\n    align-items: flex-start;\r\n    padding: 0 36px;\r\n  }\r\n\r\n  .hero h3 {\r\n    display: block;\r\n  }\r\n\r\n  form {\r\n    padding: 30px;\r\n  }\r\n}\r\n",
