  "pies-de-pagina/footer-8/styles.css": "body {\r\n  background: #111;\r\n  font-family: \"SF Pro\", \"Poppins\";\r\n}\r\n\r\n* {\r\n  box-sizing: border-box;\r\n}\r\n\r\n.container {\r\n  max-width: 800px;\r\n  margin: 0 auto;\r\n}\r\n\r\nfooter {\r\n  position: fixed;\r\n  left: 0;\r\n  bottom: 0;\r\n  right: 0;\r\n  padding: 20px;\r\n  background: linear-gradient(90deg, #1b1b1b, #161616);\r\n  display: grid;\r\n  place-content: center;\r\n  grid-template-areas:\r\n    \"logo socials\"\r\n    \"links links\";\r\n  grid-template-columns: repeat(2, 1fr);\r\n  color: #f9f9f9;\r\n}\r\n\r\nfooter::after {\r\n  content: \"\";\r\n  position: absolute;\r\n  z-index: -1;\r\n  top: 0;\r\n  left: 0;\r\n  right: 0;\r\n  height: 68px;\r\n  background: rgb(0 0 0 / 10%);\r\n}\r\n\r\n.logo {\r\n  grid-area: logo;\r\n  height: 17px;\r\n}\r\n\r\n.socials {\r\n  grid-area: socials;\r\n  display: flex;\r\n  justify-content: flex-end;\r\n  align-items: center;\r\n  gap: 20px;\r\n  font-size: 18px;\r\n}\r\n\r\n.links {\r\n  grid-area: links;\r\n  display: grid;\r\n  grid-template-columns: repeat(4, 1fr);\r\n  padding: 40px 0 50px;\r\n}\r\n\r\n.links h2 {\r\n  font-size: 13px;\r\n  font-weight: 400;\r\n  color: rgb(255 255 255 / 60%);\r\n}\r\n\r\n.links ul {\r\n  margin: 0;\r\n  padding: 0;\r\n  list-style: none;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 10px;\r\n  opacity: 0.8;\r\n  font-size: 14px;\r\n}\r\n\r\n.links address {\r\n  font-style: normal;\r\n  line-height: 1.5;\r\n  font-size: 12px;\r\n}\r\n\r\n@media (width < 500px) {\r\n  .links {\r\n    grid-template-columns: repeat(2, 1fr);\r\n    gap: 20px 0;\r\n    padding: 40px 0 30px;\r\n  }\r\n}\r\n\r\n@media (width < 360px) {\r\n  footer {\r\n    grid-template-areas: \"logo\" \"links\" \"socials\";\r\n    grid-template-columns: 1fr;\r\n  }\r\n\r\n  .socials {\r\n    justify-content: flex-start;\r\n    padding-bottom: 20px;\r\n  }\r\n}\r\n",
